/**
 * 3. Helper: Reads dates starting from Column A, Row 5 for EN, CZ, NO, SHE
 */
function getDatesData() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const result = {};

  SUPPORTED_LANGS.forEach(function(lang) {
    const sheet = ss.getSheetByName(lang);
    result[lang] = [];
    if (sheet) {
      const lastRow = sheet.getLastRow();
      if (lastRow >= START_ROW) {
        const values = sheet.getRange(START_ROW, TARGET_COLUMN, lastRow - START_ROW + 1, 1).getValues();
        for (var i = 0; i < values.length; i++) {
          const val = String(values[i][0] || '').trim();
          if (val) {
            result[lang].push(val);
          }
        }
      }
    }
  });

  return result;
}

/**
 * 4. Helper: Saves dates to Column A, starting from Row 5 for EN, CZ, NO, SHE
 */
function saveDatesData(data) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();

  SUPPORTED_LANGS.forEach(function(lang) {
    const sheet = getOrCreateTab(ss, lang);
    const dates = data[lang] || [];
    setColumnAFromRow5(sheet, dates);
  });

  return true;
}

/**
 * 5. Helper: Overwrites Column A from Row 5 downwards
 */
function setColumnAFromRow5(sheet, stringArray) {
  const lastRow = sheet.getLastRow();
  if (lastRow >= START_ROW) {
    sheet.getRange(START_ROW, TARGET_COLUMN, lastRow - START_ROW + 1, 1).clearContent();
  }

  if (stringArray && stringArray.length > 0) {
    const values = stringArray.map(function(item) {
      return [item];
    });
    sheet.getRange(START_ROW, TARGET_COLUMN, values.length, 1).setValues(values);
  }
}

/**
 * 6. Helper: Inserts / Appends single workshop to Column A from Row 5 down
 */
function insertWorkshopAtRow5(sheet, entryText) {
  if (!entryText) return;
  const lastRow = sheet.getLastRow();
  
  if (lastRow < START_ROW) {
    sheet.getRange(START_ROW, TARGET_COLUMN).setValue(entryText);
  } else {
    sheet.getRange(lastRow + 1, TARGET_COLUMN).setValue(entryText);
  }
}

/**
 * 7. Helper: Format workshop into "date: title"
 */
function formatWorkshopEntry(ws) {
  if (!ws) return '';
  if (typeof ws === 'string') return ws.trim();
  const date = ws.date || '';
  const title = ws.title || '';
  if (date && title) {
    return date + ': ' + title;
  }
  return title || date;
}

/**
 * 8. Helper: Get or insert sheet tab with headers automatically
 */
function getOrCreateTab(ss, tabName) {
  let sheet = ss.getSheetByName(tabName);
  if (!sheet) {
    sheet = ss.insertSheet(tabName);
  }
  // If the sheet has no header or less than row 5
  if (sheet.getLastRow() === 0) {
    const titles = {
      'EN': 'SHE. Academy - Workshop Dates (English Website .com)',
      'CZ': 'SHE. Academy - Workshop Dates (Czech Website .cz)',
      'NO': 'SHE. Academy - Workshop Dates (Norwegian Website .no)',
      'SHE': 'SHE. Academy Sanctuary - Workshop Dates (sheacademy.no)'
    };
    sheet.getRange('A1').setValue(titles[tabName] || ('SHE. Academy - Workshop Dates (' + tabName + ' Website)'));
    sheet.getRange('A1').setFontWeight('bold').setFontSize(13);
    sheet.getRange('A2').setValue('Target Website: ' + (tabName === 'SHE' ? 'SHE. Academy (sheacademy.no)' : tabName === 'NO' ? 'Norwegian (.no)' : tabName === 'CZ' ? 'Czech (.cz)' : 'English (.com)'));
    sheet.getRange('A2').setFontColor('#666666');
    sheet.getRange('A4').setValue('Workshop Dates (Column A, Row 5+):');
    sheet.getRange('A4').setFontWeight('bold').setFontColor('#ee5a7a');
    sheet.setFrozenRows(4);
  }
  return sheet;
}

